#include <stdio.h>

int main(void) {
    long long n;
    while (scanf("%lld", &n) == 1) {
        long long halving = 0;
        for (long long i = n; i > 0; i /= 2) {
            halving++;
        }
        printf("%lld %lld %lld\n", n * n, n * (n - 1) / 2, halving);
    }
    return 0;
}

