#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        return 0;
    }
    int values[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    int worst = 0;
    int x;
    while (scanf("%d", &x) == 1) {
        int index = -1;
        int comparisons = 0;
        for (int i = 0; i < n; i++) {
            comparisons++;
            if (values[i] == x) {
                index = i;
                break;
            }
        }
        printf("%d %d\n", index, comparisons);
        if (comparisons > worst) {
            worst = comparisons;
        }
    }
    printf("худший случай: %d\n", worst);
    return 0;
}

