#include <stdio.h>
#include <string.h>

#define LIMIT 1000000000000000000LL

// Умножает *value на factor; возвращает false, если результат превысит LIMIT.
static bool multiply(long long *value, long long factor) {
    if (*value > LIMIT / factor) {
        return false;
    }
    *value *= factor;
    return *value <= LIMIT;
}

static long long bit_length(long long n) {
    long long digits = 0;
    for (; n > 0; n /= 2) {
        digits++;
    }
    return digits;
}

int main(void) {
    char kind[8];
    long long n;
    while (scanf("%7s %lld", kind, &n) == 2) {
        long long f = 1;
        bool fits = true;
        if (strcmp(kind, "log") == 0) {
            f = bit_length(n);
        } else if (strcmp(kind, "n") == 0) {
            f = n;
        } else if (strcmp(kind, "nlog") == 0) {
            f = n;
            fits = multiply(&f, bit_length(n));
        } else if (strcmp(kind, "n2") == 0) {
            f = n;
            fits = multiply(&f, n);
        } else if (strcmp(kind, "n3") == 0) {
            f = n;
            fits = multiply(&f, n) && multiply(&f, n);
        } else if (strcmp(kind, "2n") == 0) {
            for (long long i = 0; i < n && fits; i++) {
                fits = multiply(&f, 2);
            }
        }
        if (fits) {
            printf("%lld %s\n", f, f <= 100000000 ? "да" : "нет");
        } else {
            printf("больше 10^18 нет\n");
        }
    }
    return 0;
}

